  ["Vender todo"] = "Продать всё",
  ["Vende todo lo de esta lista: lo de tus bolsas que el vendedor compra, salvo lo que necesitan tus rutas empezadas, las herramientas, tu equipo (si lo activas en las opciones) y lo que marques con clic derecho (no venderlo nunca). Mira la lista antes de pulsar."] = "Продаёт всё из этого списка: предметы из сумок, которые покупает торговец, кроме нужных для начатых маршрутов, инструментов, вашей экипировки (если включено в настройках) и предметов, отмеченных правым кликом («никогда не продавать»). Проверьте список перед нажатием.",
  ["Para que esta ventana no salga: su engranaje, o las opciones del addon (engranaje de la ventana principal o /cj opciones)."] = "Чтобы это окно не появлялось: нажмите на его шестерёнку или откройте настройки аддона (шестерёнка в главном окне или /cj opciones).",
  -- Options window
  ["General"] = "Общие",
  ["Casa de Subastas"] = "Аукционный дом",
  ["Versión %s"] = "Версия %s",
  ["Únete a nuestro Discord"] = "Наш Discord",
  ["Ideas, errores y novedades"] = "Идеи и новости",
  ["Novedades, ideas y ayuda con el addon. Copia el enlace y ábrelo en tu navegador."] = "Новости, идеи и помощь по аддону. Скопируйте ссылку и откройте её в браузере.",
  ["Ventanas, qué se propone vender, avisos y botón del minimapa."] = "Окна, предложения по продаже, уведомления и кнопка у миникарты.",
  ["No vender tu equipo"] = "Не продавать вашу экипировку",
  ["Activado, el equipo ligado a ti (tu otro equipo, lo de las misiones) y el de los conjuntos del gestor de equipo no se propone vender (ni Vender todo lo vende); los verdes sin ligar de botín, lo que fabricas y lo gris, sí. Desactivado, se propone todo: lo que quieras guardar, clic derecho y no se vende nunca."] = "Если включено, персональная экипировка (второй комплект, награды за задания) и предметы из наборов экипировки не предлагаются на продажу (и кнопка «Продать всё» их не продаст); неперсональная зелёная добыча, созданные вещи и серый хлам по-прежнему продаются. Если выключено, предлагается всё: нажмите ПКМ по нужной вещи, чтобы никогда её не продавать.",
  ["Avisos en el chat"] = "Уведомления в чате",
  ["Vendedores de recetas de stock limitado"] = "Торговцы рецептами с ограниченным запасом",
  ["La ruta cuenta con ellos: suele ser lo más barato. Venden pocas y reponen con el tiempo, y a veces otros jugadores las acaparan para revenderlas."] = "Маршрут учитывает их: обычно это самый дешёвый вариант. Они продают рецепты поштучно, запас обновляется со временем, и иногда другие игроки скупают их для перепродажи.",
  ["La ruta no cuenta con ellos: esas recetas solo se consiguen por misión o en la Casa de Subastas; si no, se usa otra receta."] = "Маршрут не учитывает их: такие рецепты берутся только за задания или на аукционе; иначе используется другой рецепт.",
  ["Su vendedor tiene stock limitado y desactivaste esos vendedores con su icono, arriba de la ruta."] = "У торговца ограниченный запас, а вы отключили таких торговцев значком над маршрутом.",
  ["Clic: abrir la receta y fabricar %d (con la profesión cerrada, el primer clic la abre)."] = "Клик: открыть рецепт и создать %d (если окно профессии закрыто, первый клик откроет его).",
  ["Clic derecho: añadir sus materiales a la lista de compra."] = "ПКМ: добавить материалы в список покупок.",
  ["Ventana junto a la profesión"] = "Окно рядом с профессией",
  ["Al abrir una profesión: lo que la pestaña Ganar dinero propone fabricar de esa profesión. Clic en una fila para fabricarlo."] = "При открытии профессии: показывает, что вкладка «Заработок» предлагает создать по этой профессии. Клик по строке запускает создание.",
  ["Ganar dinero · %s: lo que da beneficio fabricar"] = "Заработок - %s: что выгодно создавать",
  ["vender en la AH · invierte %s"] = "продать на аукционе - вложения %s",
  ["vender al vendedor · invierte %s"] = "продать торговцу - вложения %s",
  ["Clic: fabricar las de la fila (como mucho, las que dan tus materiales)."] = "Клик: создать предметы из строки (максимум столько, на сколько хватит материалов).",
  ["(%d más en la pestaña Ganar dinero)"] = "(ещё %d во вкладке «Заработок»)",
  ["Fabricarlo (sus materiales)"] = "Создать (из материалов)",
  ["Comprarlo hecho"] = "Купить готовым",
  ["sin precio"] = "нет цены",
  ["Lo más barato: comprarlo hecho."] = "Дешевле: купить готовым.",
  ["Lo más barato: fabricarlo."] = "Дешевле: создать самому.",
  ["Tiene enfriamiento (una cada pocos días): se compra hecho si se puede."] = "Есть время восстановления (раз в несколько дней): по возможности покупается готовым.",
  ["Clic: comprarlo hecho en vez de fabricarlo."] = "Клик: купить готовым вместо создания.",
  ["Clic: fabricarlo en vez de comprarlo hecho."] = "Клик: создать вместо покупки готового.",
  ["lo fabricas"] = "вы создаёте",
  ["lo compras hecho"] = "вы покупаете готовым",
  [" · no es lo más barato"] = " - не самый дешёвый вариант",
  [" · clic para cambiar"] = " - клик для смены",
  ["En la AH"] = "На аукционе",
  ["Por el chat de comercio (sin comisión)"] = "Через торговый чат (без комиссии)",
  ["Al vendedor"] = "Торговцу",
  ["Depósito: %s (%d subastas de %d h). Se devuelve si se vende: no resta del beneficio; lo pierdes si caduca."] = "Залог: %s (лотов: %d по %d ч.). Возвращается при продаже и не вычитается из прибыли; теряется, если срок лота истечёт.",
  ["Vender en:"] = "Где продавать:",
  ["AH · %d h"] = "Аукцион - %d ч.",
  ["Cara a cara (comercio): sin comisión de la AH ni depósito."] = "При личном обмене: без комиссии аукциона и залога.",
  ["Fabricar más"] = "Создать больше",
  ["Clic: escribir el precio por unidad"] = "Клик: ввести цену за штуку",
  ["Por ejemplo 6.5 (6s 50c) o 1g 20s. Vacío vuelve al precio automático; Escape no cambia nada."] = "Например, 6.5 (6с 50м) или 1з 20с. Пустое поле вернёт автоцену; Escape отменит ввод.",
  ["Fabricar menos"] = "Создать меньше",
  ["Con Mayús, de 5 en 5. Tu cantidad dura hasta el siguiente escaneo; luego vuelve a la recomendada."] = "С Shift - шагом по 5. Ваше количество сохраняется до следующего сканирования, затем возвращается к рекомендуемому.",
  [" · más de lo recomendado (%d)"] = " - больше рекомендуемого (%d)",
  ["Fabrica %d: la cantidad la elegiste tú (recomendadas: %d). Vuelve a la recomendada con el siguiente escaneo."] = "Создать %d: количество выбрано вами (рекомендуется: %d). Вернётся к рекомендуемому после следующего сканирования.",
  ["Más de lo recomendado: si no se venden, tienes el oro parado y puedes perder depósitos al caducar."] = "Больше рекомендуемого: если товар не купят, золото заморозится, а залоги сгорят по истечении срока.",
  ["%s: quitada de la Lista de compra. Tu ruta sigue empezada; vuelve a ponerla desde la vista Materiales de la ruta."] = "%s: убрано из списка покупок. Ваш маршрут остаётся активным; вернуть список можно из раздела «Материалы» маршрута.",
  ["Quitar la lista de esta ruta. La ruta sigue empezada; se vuelve a poner desde su vista Materiales."] = "Убрать список этого маршрута. Маршрут останется активным; вернуть можно из раздела «Материалы».",
  ["Lista de compra · quitada"] = "Список покупок - убран",
  ["Pulsa para volver a ponerla"] = "Нажмите, чтобы вернуть",
  ["la quitaste con la X de la Lista de compra"] = "вы убрали его кнопкой X в списке покупок",
  [" · pide objetos"] = " - требуются предметы",
  [" · cadena de %d misiones"] = " - цепочка из %d заданий",
  ["Pide: "] = "Требует: ",
  ["Antes hay que hacer 1 misión de su cadena, que también puede pedir objetos."] = "Сначала нужно выполнить 1 предыдущее задание в цепочке, для которого тоже могут потребоваться предметы.",
  ["Antes hay que hacer %d misiones de su cadena, que también pueden pedir objetos."] = "Сначала нужно выполнить %d предыдущих заданий в цепочке, для которых тоже могут потребоваться предметы.",
  [" · algo sin precio"] = " - часть предметов без цены",
  ["Lo que piden ella y su cadena:"] = "Что требуют задание и его цепочка:",
  ["Lo que no tiene precio (se consigue matando criaturas, o no se sabe cuántos pide) no cuenta en el coste."] = "То, что не имеет цены (выбивается с монстров или количество неизвестно), не учитывается в стоимости.",
  ["La ruta cuenta lo que cuesta conseguir lo que pide, comprado o fabricado. Si no te compensa, quítala con la X de la fila."] = "Маршрут учитывает стоимость требуемых предметов, купленных или изготовленных. Если вам это не подходит, уберите рецепт кнопкой X в строке.",
  ["stock limitado · no se cuentan"] = "ограниченный запас - не учитываются",
  ["X de la fila: quitar esta receta y que la ruta busque otra (se recupera con la fila de recetas quitadas)."] = "X в строке: убрать этот рецепт, чтобы маршрут подобрал другой (вернуть можно через строку убранных рецептов).",
  ["Tras un escaneo: recetas de botín que te faltan y están en la AH, y si tu ruta empezada cuesta bastante más con los precios nuevos. Desactivados, la ruta lo sigue diciendo en su línea de estado."] = "После сканирования: сообщает о недостающих рецептах из добычи на аукционе и о сильном удорожании начатого маршрута. Если отключить, маршрут всё равно покажет это в строке состояния.",
  ["Botón del minimapa"] = "Кнопка у миникарты",
  ["El botón de Crafter's Journal junto al minimapa. También con /cj minimap."] = "Кнопка Журнал ремесленника у миникарты. Также переключается командой /cj minimap.",
  ["Tu equipo (ligado a ti o en un conjunto del gestor de equipo): no se propone venderlo, para no venderlo sin querer. Se cambia en /cj opciones."] = "Ваша экипировка (персональная или из наборов экипировки): не предлагается на продажу, чтобы не продать случайно. Настраивается в /cj opciones.",
  ["tu equipo: no se vende"] = "ваша экипировка: не продаётся",
  ["Ventana junto al vendedor"] = "Окно рядом с торговцем",
  ["Al abrir un vendedor: lo que te falta de la lista de compra y lo que puedes venderle, con los botones Comprar todo y Vender todo."] = "При открытии торговца: показывает недостающие товары из списка покупок и вещи на продажу с кнопками «Купить всё» и «Продать всё».",
  ["Lista de compra junto a la Casa de Subastas"] = "Список покупок рядом с аукционом",
  ["Tamaño de las tandas (recetas verdes)"] = "Размер партий (зелёные рецепты)",
  ["En verde no todas las fabricaciones suben punto: la ruta compra para unas tantas y, al gastarlas, la siguiente. Más grande, menos viajes a la AH; más pequeña, menos material de sobra si tienes suerte."] = "На зелёных рецептах не каждое создание повышает навык: маршрут закупает материалы на несколько попыток, а когда они закончатся — на следующую партию. Больше размер — меньше походов на аукцион; меньше размер — меньше лишних материалов, если повезёт.",
  ["Cada tanda es de unas %d fabricaciones: se cambia en /cj opciones, Lista de compra."] = "Каждая партия рассчитана примерно на %d созданий: настраивается в /cj opciones («Список покупок»).",
  ["Al abrir la AH: los materiales de tu ruta que te faltan, para comprarlos. Desactivada, se sigue pudiendo abrir con el botón de encima de la AH."] = "При открытии аукциона: показывает недостающие материалы для маршрута. Если отключить, окно всё равно можно открыть кнопкой над аукционом.",
  ["Vender en la AH desde tus bolsas"] = "Продажа на аукционе из сумок",
  ["Opciones"] = "Настройки",
  -- WhatsNew
  ["Novedades"] = "Что нового",
  ["Crafter's Journal %s: esto es lo nuevo desde la última vez."] = "Журнал ремесленника %s: нововведения с прошлого обновления.",
  ["¡Entendido!"] = "Понятно!",
  ["Siguiente"] = "Далее",
  ["Precios del vendedor, siempre los del juego"] = "Цены торговцев — всегда из игры",
  ["El addon ya no deduce lo que paga el vendedor del dinero que te entra al vender: con dos ventas cobradas juntas podía apuntar el doble, y Ganar dinero prometía de más. Ahora usa siempre el precio del juego."] = "Аддон больше не вычисляет цену продажи торговцу по полученным монетам: при продаже двух предметов сразу цена могла удваиваться. Теперь всегда используется точная цена из игры.",
  ["Aprender una receta, solo si compensa"] = "Изучение рецепта — только если выгодно",
  ["La ruta ya no te manda al instructor a aprender una receta para unas pocas fabricaciones que ahorran unas monedas: esos puntos los hace con la receta de al lado, salvo que ahorre más de 5s."] = "Маршрут больше не отправляет к учителю ради пары созданий с экономией в несколько медяков: эти очки набираются соседним рецептом, если экономия не превышает 5 сер.",
  ["Se ve cuándo esperar en la AH"] = "Видно, когда нужно подождать на аукционе",
  ["Mientras se escanea la AH, la ventana de vender queda tapada con un reloj de arena y el progreso: así no anuncias a precios viejos sin querer."] = "Во время сканирования аукциона окно продажи закрывается песочными часами и шкалой прогресса, чтобы вы случайно не выставили товары по старым ценам.",
  ["Nueva pestaña: Merchant's Favor"] = "Новая вкладка: Торговое обязательство",
  ["Con qué llenar tus Waylaid Crates al menor coste y qué cajas de la AH dan el Favor más barato por punto. Clic en una fila para añadirlo a la lista de compra."] = "Чем дешевле всего заполнить ваши ящики с припасами (Waylaid Crates) и какие ящики с аукциона дают самую выгодную цену за единицу торгового обязательства. Нажмите на строку, чтобы добавить в список покупок.",
  ["Más fluido"] = "Более плавная работа",
  ["Sin tirones al acabar un escaneo ni al entrar, fabricar en serie va fluido y el addon apenas trabaja mientras juegas por el mundo."] = "Больше никаких фризов при входе в игру и после сканирования, серийное создание работает плавно, а аддон почти не нагружает систему во время игры.",
  ["Cuánto se tarda en fabricar"] = "Время на изготовление",
  ["Cada paso de la ruta dice cuánto se tarda en fabricarlo (en naranja si es lento) y el total, el de toda la ruta. \"Menos fabricaciones\" ahora también evita las recetas lentas."] = "На каждом шаге маршрута указано время изготовления (оранжевым, если долго), а в итоге — общее время маршрута. Опция «Меньше созданий» теперь также избегает долгих рецептов.",
  ["Ganar dinero, más fiable"] = "«Заработок» стал надёжнее",
  ["Solo fabrica lo intermedio con recetas que sabes y dice qué fabricar antes. Enseña cuánto ya llevas en las bolsas, y las filas del lote no cambian de sitio al pulsar - o +."] = "Промежуточные материалы создаются только по известным вам рецептам, с подсказкой, что сделать заранее. Показывает запас в сумках, а строки партии не прыгают при нажатии - или +.",
  ["Quitar una ventana, en un clic"] = "Отключение окна в один клик",
  ["El engranaje de las ventanas junto al vendedor, la AH y la profesión abre un menú con \"No mostrar esta ventana\", sin buscarla en las opciones."] = "Шестерёнка в окнах рядом с торговцем, аукционом и профессией открывает меню с пунктом «Не показывать это окно», без поиска в настройках.",
  ["Buscar en la AH con Mayús+clic"] = "Поиск на аукционе через Shift+клик",
  ["Mayús+clic en un objeto del addon lo busca en la AH (o lo enlaza en el chat). Y la lista de compra junto a la AH tiene una X en cada lista para quitarla."] = "Shift+клик по предмету в аддоне ищет его на аукционе (или вставляет ссылку в чат). А в списке покупок у аукциона у каждого списка есть крестик X для удаления.",
  ["Vista de desarrollo: no cuenta como vista."] = "Режим разработки: не отмечается как просмотренное.",
  ["Ahora en alemán y francés"] = "Теперь на немецком и французском",
  ["Textos, recetas y objetos en alemán y francés, con los nombres del juego. Se cambia con el selector de idioma de arriba. Si ves una traducción mejorable, dínoslo en Discord."] = "Тексты, рецепты и предметы на немецком и французском языках с игровыми названиями. Переключается в меню выбора языка сверху.",
  ["Cada ventana, con su propia opción"] = "Отдельная настройка для каждого окна",
  ["Las ventanas que salen solas junto al vendedor, la Casa de Subastas y la profesión tienen un engranaje que abre las opciones. La lista de compra y la de vender en la AH ya se quitan por separado."] = "Окна, автоматически открывающиеся рядом с торговцем, аукционом и профессией, получили значок шестерёнки для перехода в настройки. Список покупок и окно продажи на аукционе теперь отключаются раздельно.",
  ["Confirmar antes de anunciar"] = "Подтверждение перед выставлением",
  ["Al anunciar más de una unidad de golpe se pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón. Se puede desactivar."] = "При выставлении больше одной штуки за раз теперь запрашивается количество и цена, чтобы случайный клик не выставил всю стопку. Можно отключить.",
  ["La AH sin tirones"] = "Аукцион без подвисаний",
  ["Al acabar un escaneo (el tuyo o el de otro addon, como Auctionator) los precios se guardan poco a poco y el juego ya no se congela. Nueva opción para no leer los escaneos de otros addons."] = "После завершения сканирования (вашего или другого аддона, например Auctionator) цены сохраняются плавно, и игра больше не зависает. Добавлена опция отключения чтения сканирований других аддонов.",
  ["Rutas sin enfriamientos"] = "Маршруты без перезарядок",
  ["Las transmutaciones y el Mooncloth tienen enfriamiento: la ruta ya no pide 186 transmutaciones seguidas. Como mucho las usa para un punto."] = "У трансмутаций и луноткани есть время восстановления, поэтому маршрут больше не требует 186 трансмутаций подряд - максимум на одно очко навыка.",
  ["Lista de compra en su sitio"] = "Список покупок на своём месте",
  ["Al cerrar la ventana de vender en la AH, la lista de compra se pega a la AH y no deja un hueco."] = "При закрытии окна продажи на аукционе список покупок теперь пристыковывается к окну аукциона без пустого зазора.",

  ["Confirmar antes de anunciar en la AH"] = "Подтверждать выставление на аукцион",
  ["Al anunciar más de una unidad de golpe (ventana de vender, Inventario, ruta), pregunta antes cuántas y a qué precio. Así un clic sin querer no anuncia un montón."] = "При выставлении больше одной штуки за раз (в окне продажи, инвентаре или маршруте) запрашивает подтверждение количества и цены, чтобы случайный клик не выставил целую стопку.",
  ["Duración de las subastas"] = "Длительность аукционов",
  ["Automática: 24 h lo que se vende bien y 8 h lo dudoso (si caduca, pierdes menos depósito). O la misma siempre: más corta, depósito más barato y vuelves a anunciar antes. Vale para la ventana de vender, el Inventario y la ruta."] = "Автоматически: 24 ч для того, что хорошо продаётся, и 8 ч для сомнительного (если лот истечёт, вы потеряете меньше залога). Или всегда одна и та же: чем короче, тем дешевле залог и тем раньше вы выставляете заново. Действует для окна продажи, инвентаря и маршрута.",
  ["Automática"] = "Автоматически",
  ["2 h"] = "2 ч",
  ["8 h"] = "8 ч",
  ["24 h"] = "24 ч",
