  ["¿Anunciar %d × %s a %s cada uno (%d h)?"] = "Выставить %d × %s по %s за шт. (%d ч.)?",
  ["Clic: dejar de mostrar esta ventana, o ver todas las opciones."] = "Клик: скрыть это окно или открыть все настройки.",
