  [": falta "] = ": не хватает ",
  ["Si consigues esos materiales (o aparecen en la AH), el plan las usará."] = "Если вы добудете эти материалы (или они появятся на аукционе), план использует эти рецепты.",
  ["No hay ninguna receta de instructor mejor en este tramo: esta es la única opción."] = "На этом этапе у учителя нет рецептов лучше: это единственный вариант.",
  ["Materiales de este paso:"] = "Материалы для этого шага:",
  ["Probabilidad de subir: del %d%% al %d%%"] = "Шанс повышения навыка: с %d%% до %d%%",
  ["fabricarlo (%s): %s/u · comprarlo hecho: %s/u"] = "создать (%s): %s/шт. - купить готовым: %s/шт.",
  ["comprado: %s/u · fabricarlo (%s): %s/u"] = "покупка: %s/шт. - создать (%s): %s/шт.",
  ["fabricarlo quitaría puntos a %s"] = "создание заберёт очки прокачки у «%s»",
  ["Guarda %d para pasos posteriores."] = "Оставьте %d для следующих шагов.",
  ["Vendido al vendedor recuperas %s por fabricación."] = "При продаже торговцу вернётся %s за создание.",
  ["Lenta: %s por fabricación."] = "Долгий рецепт: %s на одно создание.",
  ["Si prefieres otra receta, quítala con la X (o activa \"Menos fabricaciones\", que evita las lentas)."] = "Если хотите другой рецепт, уберите этот крестиком X (или включите «Меньше созданий», чтобы избегать долгих).",
  ["Si lo vendes en la AH podrías sacar hasta %s más en este paso, pero no se sabe cuántos se venden."] = "При продаже на аукционе можно получить до %s больше на этом шаге, но неизвестно, сколько удастся продать.",
  ["Precio poco fiable: "] = "Ненадёжная цена: ",
  ["Fabricas %d en total en el plan."] = "Всего по плану создаётся: %d.",
  ["Guarda %d (no los vendas):"] = "Оставьте %d (не продавайте):",
  [" (paso %d-%d)"] = " (шаг %d-%d)",
  ["  %dx para %s%s"] = "  %d× для %s%s",
  ["Te sobran %d. El plan cuenta venderlos al vendedor a %s cada uno."] = "Остаётся лишних: %d. План рассчитывает продать их торговцу по %s за шт.",
  ["En la AH te quedarían %s cada uno igualando a la más barata (subasta de 24 h, comisión y depósito de %s descontados): hasta %s más en total."] = "На аукционе вы получите по %s за шт., уравняв с самой низкой ценой (аукцион на 24 ч., с вычетом комиссии и залога %s): всего до %s больше.",
  ["Pero el juego no dice cuántos se venden: puede que no los vendas todos, o ninguno. Anuncia unos pocos y mira las alertas:"] = "Однако игра не показывает, сколько товара купят: возможно, уйдёт не всё или не купят ничего. Выставьте немного и следите за подсказками:",
  ["Consejo: pon los %d en la AH a %s (1 cobre menos que la más barata)."] = "Совет: выставьте все %d на аукцион по %s (на 1 медяк дешевле самой низкой цены).",
  ["Consejo: pon solo %d en la AH a %s para probar y vende el resto al vendedor; si se venden, anuncia más."] = "Совет: выставьте на аукцион только %d по %s для пробы, а остальное продайте торговцу; если купят, выставите ещё.",
  ["Consejo: con estas alertas, mejor véndelos al vendedor."] = "Совет: с такими предупреждениями лучше продать их торговцу.",
  ["Consejo: véndelos al vendedor; en la AH no compensa la diferencia."] = "Совет: продайте их торговцу; разница на аукционе того не стоит.",
  ["%d uds a %s de media, comprando de la más barata a la más cara (ahora hay %d a la venta)."] = "%d шт. в среднем по %s при скупке от самых дешёвых к более дорогим (сейчас в продаже %d).",
  ["Hacen falta más de las que hay: las %d que faltan se cuentan al precio típico (mediana)."] = "Требуется больше, чем есть в продаже: недостающие %d учтены по типичной цене (медиане).",
  ["Vendedor más cercano"] = "Ближайший торговец",
