  -- Earn / EarnUI / ganar dinero
  ["Se vende al vendedor: venta segura, sin límite de ventas."] = "Продаётся торговцу: гарантированная продажа без ограничений.",
  ["Hasta aquí: más allá, los materiales que quedan en la AH salen tan caros que la siguiente ya no compensa."] = "Стоп здесь: дальше оставшиеся на аукционе материалы стоят слишком дорого, и следующее создание не окупится.",
  ["Hasta aquí: no quedan más materiales a la venta en la AH."] = "Стоп здесь: на аукционе больше нет материалов в продаже.",
  ["Tope de %d fabricaciones: con más aún daría beneficio."] = "Ограничение в %d созданий: большее количество всё ещё приносило бы прибыль.",
  ["Cada línea del vendedor se calcula por separado: si dos usan los mismos materiales, haz una."] = "Каждая строка для торговца рассчитывается отдельно: если две используют одни и те же материалы, выберите одну.",
  ["Ganar dinero: %d× %s"] = "Заработок: %d× %s",
  ["Venta segura al vendedor"] = "Гарантированная продажа торговцу",
  ["BulkMoney"] = "BulkMoney",
  ["Fabricar en cantidad para vender al vendedor: qué recetas, de cualquier profesión, dejan más oro por hora de fabricar."] = "Массовое создание для продажи торговцам: какие рецепты любой профессии приносят больше всего золота за час создания.",
  ["Recetas de todas las profesiones (las sepas o no) que dejan beneficio vendiendo lo fabricado al vendedor. Cada fila es una hora de fabricar y su cifra, el oro por hora."] = "Рецепты всех профессий (известные и нет), которые приносят прибыль при продаже созданного торговцу. Каждая строка — час создания, а её число — золото в час.",
  ["Bartering (-10% en vendedores)"] = "Bartering (-10% у торговцев)",
  ["Talento de legado, rango 2/2: los vendedores te cobran un 10% menos. Márcalo si lo tienes: lo que se compra al vendedor sale más barato."] = "Талант наследия, ранг 2/2: торговцы берут на 10% меньше. Отметьте, если он у вас есть: покупки у торговцев станут дешевле.",
  ["Precios de la AH de hace %d min"] = "Цены аукциона %d мин назад",
