  ["pendiente"] = "ожидание",
  ["Un cebo vendido en menos de %d s lo suele comprar un sniper, y entonces nadie rebaja por debajo de él: sube el precio hasta que deje de pasar. La sugerencia va entre el más caro comprado al instante y el más barato que aguantó."] = "Приманку, проданную быстрее чем за %d с, обычно покупает снайпер, и тогда никто не ставит дешевле: поднимайте цену, пока это не прекратится. Предложенная цена лежит между самой дорогой купленной сразу и самой дешёвой, которая продержалась.",
  ["Quitar de BulkMoney"] = "Убрать из BulkMoney",
  ["No volver a proponer esta receta aquí: por ejemplo, si no sabes conseguir su patrón. No la quita de Ganar dinero. Se recupera con la fila de recetas quitadas, al final de la lista."] = "Больше не предлагать этот рецепт здесь: например, если вы не знаете, где взять выкройку. Из «Заработка» он не убирается. Вернуть можно строкой убранных рецептов в конце списка.",
  ["Recetas quitadas de BulkMoney: %d"] = "Рецептов убрано из BulkMoney: %d",
  ["Quitadas de BulkMoney"] = "Убраны из BulkMoney",
  ["No se sabe dónde se consigue su receta (quizá un botín raro): sale por si tú o alguien de tu cuenta la tiene."] = "Неизвестно, где взять этот рецепт (возможно, редкая добыча): он показан на случай, если он есть у вас или у кого-то на вашей учётной записи.",
  ["En la AH hay para %d fabricaciones (~%d h): compensa comprar ya también lo de las horas siguientes."] = "На аукционе хватит на %d созданий (~%d ч): выгодно купить сейчас и на следующие часы.",
  ["se acaba en ~%d min"] = "закончится через ~%d мин",
  ["Lo que cabe en una hora de fabricar: más horas aún darían beneficio. Compensa si fabricas sin estar delante."] = "Столько помещается в час создания: дополнительные часы всё ещё приносили бы прибыль. Выгодно, если создавать, не сидя за компьютером.",
  ["Solo unos %d min de fabricar: es lo que deja en una hora."] = "Всего около %d мин создания: больше за час не заработать.",
  ["Ninguna receta deja beneficio vendiéndola al vendedor con los precios de este escaneo."] = "По ценам этого сканирования ни один рецепт не приносит прибыли при продаже торговцу.",
  ["%s/h"] = "%s/ч",
  ["al aprender la profesión"] = "при изучении профессии",
  ["No tienes %s: es para otro personaje."] = "У вас нет профессии «%s»: это для другого персонажа.",
