  ["Al pulsar Vender todo en la ventana junto al vendedor, pregunta antes qué vende y por cuánto."] = "При нажатии «Продать всё» в окне у торговца запрашивает подтверждение списка и суммы.",
  ["Confirmar antes de Comprar todo"] = "Подтверждать «Купить всё»",
  ["Al pulsar Comprar todo en la ventana junto al vendedor, pregunta antes cuántos materiales compra y por cuánto."] = "При нажатии «Купить всё» в окне у торговца запрашивает подтверждение количества и суммы.",
  ["Confirmar antes de vender todo al vendedor"] = "Подтверждать продажу всего торговцу",
  ["Al pulsar el botón de vender al vendedor de la pestaña Inventario, pregunta antes cuántos objetos vende y por cuánto."] = "При нажатии кнопки продажи торговцу во вкладке «Инвентарь» запрашивает подтверждение количества и суммы.",
  ["Mostrar las novedades al actualizar"] = "Показывать список изменений при обновлении",
  ["Tras actualizar el addon, una ventana con lo nuevo de esa versión (una vez por versión). También se quita con su casilla \"No volver a mostrar\"."] = "После обновления аддона показывает окно с новинками версии (один раз). Также отключается галочкой «Больше не показывать».",
  ["Ya no se mostrarán las novedades. Se vuelven a activar en /cj opciones (General)."] = "Список изменений больше не будет показываться. Включить можно в /cj opciones («Общие»).",
  ["No volver a mostrar"] = "Больше не показывать",
  ["Clic: seleccionarlo y marcarlo con una estrella (si está cerca)."] = "Клик: выбрать в цель и отметить звездой (если рядом).",
  ["Controles siempre visibles"] = "Кнопки управления всегда видны",
  ["Activado, los controles alrededor del asistente (flechas de pasos, modo de compra, saltar, cerrar) se ven siempre. Desactivado, se despliegan al pasar el ratón por el asistente y se pliegan al salir."] = "Если включено, кнопки вокруг помощника (стрелки шагов, режим закупки, пропуск, закрытие) видны постоянно. Если выключено, выезжают при наведении курсора и скрываются при уводе.",
  ["Clic para marcarlo"] = "Клик, чтобы отметить",
  ["Encima del asistente, una flecha que te lleva al instructor o al vendedor del paso, con las yardas y el tiempo. Al pulsar el banner se marca además el camino como en la ventana del addon."] = "Над помощником отображается стрелка к учителю или торговцу текущего шага с расстоянием и временем. Клик по баннеру также прокладывает маршрут.",
  ["Saltar"] = "Пропустить",
  ["ruta entera"] = "весь маршрут",
  ["ya puedes · antes de %d"] = "уже можно - до %d",
  ["aprende también: %s"] = "изучите также: %s",
  ["Comprado: %s"] = "Куплено: %s",
  ["Buzón"] = "Почтовый ящик",
  ["+%d después"] = "+%d позже",
  ["Guarda las otras %d: no se sabe si se venden bien, así que anuncia unas pocas y, cuando se vendan, las siguientes (aunque sea en varios días). En la AH valen más que en el vendedor."] = "Оставьте остальные %d: неизвестно, насколько хорошо они продаются, поэтому выставляйте понемногу и по мере продажи добавляйте следующие (пусть даже за несколько дней). На аукционе они стоят дороже, чем у торговца.",
  ["Siguiendo el consejo (AH y vendedor)"] = "По рекомендации (аукцион и торговец)",
  ["Lo del vendedor es seguro; lo de la AH, si se vende"] = "Доход от торговца гарантирован; с аукциона — если купят",
  ["con AH: "] = "с аукционом: ",
  ["Vendiendo al vendedor (seguro)"] = "Продажа торговцу (гарантированно)",
  ["El segundo total cuenta lo que la vista %s aconseja anunciar en la AH a su precio actual. No es seguro: depende de que se venda, a ese precio y antes de que caduque la subasta. Lo del vendedor sí es seguro."] = "Второй итог учитывает предметы, которые во вкладке «%s» советуется выставить на аукцион по текущей цене. Это не гарантировано и зависит от того, купят ли лот до истечения срока. Продажа торговцу гарантирована.",
  ["Para seguir fabricando, compra más"] = "Чтобы продолжить создание, докупите ещё",
  ["Clic: aprenderlo en este instructor."] = "Клик: изучить у этого учителя.",
  ["Este instructor no lo enseña (o aún no te llega el nivel)."] = "Этот учитель не обучает этому рецепту (или ваш уровень ещё недостаточен).",
  ["Buzón más cercano"] = "Ближайший почтовый ящик",
  ["Recoge el correo"] = "Заберите почту",
  ["Lo comprado en la AH: "] = "Куплено на аукционе: ",
  ["%d objetos comprados en la AH"] = "Куплено предметов на аукционе: %d",
  ["Lo que compraste en la AH para esta ruta. Este paso se da por hecho cuando lo tienes en las bolsas."] = "То, что вы купили на аукционе для этого маршрута. Шаг засчитается, когда предметы окажутся в сумках.",
  ["Comprada en la AH · apréndela antes de fabricar"] = "Куплен на аукционе - изучите перед созданием",
  ["aprende %s primero"] = "сначала изучите «%s»",
  ["Compra detectada: %s ×%d. Cuenta ya para la ruta y la lista de compra."] = "Зафиксирована покупка: %s ×%d. Уже учтено в маршруте и списке покупок.",
  ["compra también %s"] = "купите также %s",
  ["fabrica aquí hasta %s"] = "создавайте здесь до %s",
  ["Los pasos de compra y la Lista de compra piden solo lo del tramo en el que estás."] = "Шаги закупки и список покупок запрашивают материалы только для текущего этапа.",
  ["Los pasos de compra y la Lista de compra piden lo que falta para toda la ruta, de una vez."] = "Шаги закупки и список покупок запрашивают сразу всё, чего не хватает на весь маршрут.",
  ["Es el modo de ahora."] = "Текущий режим.",
  ["Clic: cambiar a este modo."] = "Клик: переключиться на этот режим.",
  ["Cómo funciona el asistente"] = "Как работает помощник",
  ["Abrir la ruta en la ventana"] = "Открыть маршрут в окне",
  ["La ruta entera, en el paso en el que estás: ahí puedes quitar una receta, cambiar las opciones de la ruta o dejarla."] = "Весь маршрут на текущем шаге: там можно убрать рецепт, изменить настройки маршрута или сбросить его.",
  ["Clic: la explicación, paso a paso."] = "Клик: подробное пошаговое объяснение.",
  ["Te guía paso a paso por tu ruta empezada, sin abrir la ventana: enseña el mismo paso que la vista Ruta."] = "Ведёт вас по начатому маршруту шаг за шагом без открытия основного окна: показывает тот же шаг, что и вкладка «Маршрут».",
  ["Bloquearlo o sacarlo solo al empezar una ruta: /cj opciones, Asistente de ruta."] = "Закрепить окно или открывать только при старте маршрута: /cj opciones («Помощник маршрута»).",
  ["Un clic en el banner hace lo que toca"] = "Клик по баннеру выполняет следующее действие",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra; con el banco, saca a las bolsas justo lo que falta. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "При открытом аукционе покупает следующий материал; у торговца — закупает нужное; в банке — забирает недостающее в сумки. Если окна закрыты — прокладывает маршрут к ближайшему НИП. Ничего не покупает без вашего клика.",
  ["El color dice qué toca"] = "Цвет подсказывает текущее действие",
  ["¿Por qué pide más fabricaciones de las que me dan los materiales?"] = "Почему указано больше созданий, чем хватает материалов?",
  ["La ruta compra por tandas: en las recetas amarillas y verdes no todas suben punto. \"Esta tanda: N\" es para cuántas te llega lo que llevas. Con suerte basta; si no, al acabarla te manda a comprar más."] = "Маршрут закупает партиями: на жёлтых и зелёных рецептах не каждая попытка повышает навык. «Эта партия: N» показывает, на сколько созданий хватит текущих материалов. Если повезёт — хватит; если нет, аддон отправит докупить ещё.",
  ["¿Qué significa el número de \"Fabrica N×\"?"] = "Что означает число в «Создайте N×»?",
  ["Es lo que te falta de media para acabar el paso, según los puntos que te quedan. Baja con cada fabricación; si tienes mala suerte y el punto no sube, se queda quieto hasta que lo subas."] = "Это среднее число созданий, нужное для завершения шага с учётом оставшихся очков навыка. Оно уменьшается при каждом повышении; если навык не вырос, число не меняется.",
  ["Lo tengo de otro sitio (comercio, hermandad, otro personaje)"] = "Получено другим способом (обмен, банк гильдии, твинк)",
  ["En el paso de compra, pulsa Saltar: lo da por comprado en este tramo. Lo comprado en la AH ya cuenta aunque siga en el correo."] = "На шаге покупки нажмите «Пропустить»: материалы засчитаются как купленные на этом этапе. Купленное на аукционе учитывается, даже если ещё лежит на почте.",
  ["¿Y si fabrico otra cosa o voy por otro orden?"] = "А если я создам что-то другое или пойду в другом порядке?",
  ["La ruta mira tu nivel y tus bolsas, no lo que fabricaste: se pone al día sola. Si gastaste materiales, te mandará a comprar lo que falte."] = "Маршрут отслеживает ваш уровень навыка и содержимое сумок, а не конкретные действия, и сам подстраивается. Если вы потратили материалы, он предложит докупить недостающее.",
  ["Comprar o ir al banco"] = "Купить или зайти в банк",
  ["Ir a un PNJ"] = "Отправиться к НИП",
  ["La flecha te lleva al PNJ"] = "Стрелка указывает путь к НИП",
  ["Sale cuando el paso tiene un PNJ: verde si vas bien, roja si vas al revés. También lo marca en el mapa y el minimapa. En otro continente te dice qué barco o zepelín tomar."] = "Появляется, когда шаг связан с НИП: зелёная, если вы движетесь верно, красная — если в обратную сторону. Также ставит метку на карте и миникарте. На другом континенте подскажет нужный корабль или дирижабль.",
  ["Con la AH abierta, compra el siguiente material; con un vendedor, le compra. Si no tienes nada abierto, te lleva al PNJ más cercano. Nunca compra sin tu clic."] = "При открытом аукционе покупает следующий материал; у торговца — закупает нужное. Если окна закрыты — прокладывает путь к ближайшему НИП. Ничего не покупает без вашего клика.",
  ["Comprar"] = "Купить",
  ["Comprar: por tramos"] = "Закупка: по этапам",
  ["Comprar: ruta entera"] = "Закупка: весь маршрут",
  ["Saltar este paso"] = "Пропустить этот шаг",
  ["Recuperar"] = "Вернуть",
  ["Recuperar este paso"] = "Вернуть этот шаг",
  ["Lo saltaste: vuelve a pedirte comprarlo."] = "Вы пропустили этот шаг: покупка снова требуется.",
  ["Si te equivocas, vuelve a él con la flecha de paso anterior y pulsa Recuperar."] = "Если ошиблись, вернитесь к шагу стрелкой назад и нажмите «Вернуть».",
  ["Saltado · Recuperar lo vuelve a poner"] = "Пропущено - «Вернуть» восстановит шаг",
  ["Lo das por comprado y pasa al siguiente paso. Para lo que el addon no ve (el chat de comercio, el banco de hermandad, un alter). Solo en este tramo."] = "Отмечает материалы как купленные и переходит к следующему шагу. Полезно, если вы взяли их из банка гильдии, купили с рук или переслали с другого персонажа. Только для текущего этапа.",
  ["Lo comprado en la AH ya cuenta aunque siga en el correo."] = "Купленное на аукционе уже учитывается, даже если ещё на почте.",
  ["Quitar de Ganar dinero"] = "Убрать из «Заработка»",
  ["No volver a proponer esta receta aquí: por ejemplo, si pide una estación que no tienes. Se recupera con la fila de recetas quitadas, al final de la lista."] = "Больше не предлагать этот рецепт здесь (например, если у вас нет нужной кузницы/наковальни). Вернуть можно через строку убранных рецептов внизу списка.",
  ["Recetas quitadas de Ganar dinero: %d"] = "Рецептов убрано из «Заработка»: %d",
  ["Quitadas de Ganar dinero"] = "Убраны из «Заработка»",
  ["En las recetas verdes (y a veces en las amarillas) no todas las fabricaciones suben punto, así que la ruta compra por tandas: cuando gastas una, te trae a comprar la siguiente y luego vuelves a fabricar."] = "На зелёных (а иногда и жёлтых) рецептах не каждое создание повышает навык, поэтому маршрут закупает партиями: израсходовав одну, вы докупаете следующую и продолжаете создание.",
  ["BETA"] = "БЕТА",
  ["Asistente de ruta (beta)"] = "Помощник маршрута (бета)",
  ["Está en pruebas. Si ves algo raro, abre un post en el canal de bugs de nuestro Discord: el enlace está en el botón Informar de un error, arriba a la izquierda de la ventana del addon."] = "Функция в бета-тесте. Если заметите ошибку, напишите в канал багов нашего Discord (ссылка в кнопке «Ошибка» в левом верхнем углу окна аддона).",
  ["Si no quieres usarlo, desactívalo en /cj opciones, Asistente de ruta."] = "Если помощник не нужен, отключите его в /cj opciones («Помощник маршрута»).",
  ["los %d que hacen falta"] = "все %d требуемых",
  ["%d en total · tienes %d"] = "всего %d - у вас %d",
  ["%d en total"] = "всего %d",
  ["Demanda (TSM, región): ~%s vendidos al día, tasa de venta %s"] = "Спрос (TSM, регион): ~%s продаж в день, доля продаж %s",
  ["Demanda (TSM): sin datos de este objeto (¿la app de TSM está al día?)"] = "Спрос (TSM): нет данных об этом предмете (приложение TSM обновлено?)",
  ["TSM: en la región se vende de media a %s, bastante menos que los %s con los que se cuenta aquí."] = "TSM: в регионе продаётся в среднем по %s, что заметно ниже %s в текущем расчёте.",
  ["Poca demanda según TSM y otra alerta en contra: aunque el margen parezca bueno, probablemente no lo venderás."] = "Низкий спрос по данным TSM и ещё один негативный сигнал: даже при хорошей наценке продать будет сложно.",
  ["TSM: en la región se venden ~%s al día: como mucho lo que se vende en %d días."] = "TSM: в регионе продаётся ~%s в день - не больше объёма продаж за %d дн.",
  ["Usar la demanda de TSM"] = "Учитывать спрос TSM",
  ["Si tienes TSM con su app de escritorio: cuántos se venden al día en la región y qué parte de lo que se anuncia se vende. Es una alerta más de mercado y no se proponen más de los que se venden en 2 días. Tus escaneos siguen mandando."] = "Если установлен TSM с десктопным приложением: учитывает суточные продажи в регионе и долю выкупа. Добавляет сигнал рынка и ограничивает партию объёмом продаж за 2 дня. Ваши сканирования всегда в приоритете.",
  ["receta con enfriamiento, una cada vez."] = "рецепт с перезарядкой, по одной штуке за раз.",
  ["No se sabe aún si su enfriamiento está listo: al abrir la profesión se comprueba (si no lo está, sale del lote)."] = "Пока неизвестно, прошла ли перезарядка: проверяется при открытии окна профессии (если на перезарядке, убирается из партии).",
  [" · enfriamiento: ¿listo?"] = " - перезарядка: готово?",
  [" · enfriamiento listo"] = " - перезарядка прошла",
  ["Abre la profesión para saber si está listo"] = "Откройте профессию, чтобы проверить перезарядку",
  ["Listo: está en el lote de hoy"] = "Готово: добавлено в партию на сегодня",
  ["Demanda de TSM: vendidos al día, mínimo"] = "Спрос TSM: минимум продаж в день",
  ["Por debajo, alerta de poca demanda (y no se propone aprender la receta). Cuenta toda la región: tu reino vende como mucho eso."] = "Ниже этого порога выдаётся предупреждение о низком спросе (и изучение рецепта не предлагается). Учитывается весь регион.",
  ["Demanda de TSM: tasa de venta mínima"] = "Спрос TSM: минимальная доля продаж",
  ["Qué parte de lo que se anuncia acaba vendiéndose (1 = todo). Por debajo, alerta de poca demanda."] = "Какая доля выставленных лотов в итоге продаётся (1 = все). Ниже порога выдаётся предупреждение о низком спросе.",
  ["%s al día"] = "%s в день",
  ["No cuenta"] = "Выкл.",
  ["Tiene enfriamiento (una cada vez): lo que cuesta aprenderla se recupera en %d fabricaciones."] = "Есть перезарядка (по 1 шт. за раз): стоимость изучения окупится за %d созданий.",
  ["Tiene enfriamiento: se puede fabricar una cada vez."] = "Есть перезарядка: можно создавать по 1 шт. за раз.",
  [" · con enfriamiento"] = " - с перезарядкой",
  ["Este vendedor no tiene: %s. Sigue la fila para ir a otro."] = "У этого торговца нет: %s. Нажмите на строку, чтобы пойти к другому.",
  ["Nuevo: asistente de ruta (beta)"] = "Новое: помощник маршрута (бета)",
  ["Con una ruta empezada, un banner pequeño te dice qué toca: fabricar, comprar en la AH o al vendedor, recoger el correo o entrenar. Un clic lo hace o te lleva. Se abre con el botón junto a Dejar ruta o con /cj mini."] = "При активном маршруте компактный баннер подсказывает текущую задачу: создать, купить на аукционе или у торговца, забрать почту или обучиться. Один клик выполняет действие или ведёт к цели. Открывается кнопкой у «Сбросить маршрут» или командой /cj mini.",
  ["Cuánto se tarda en fabricar"] = "Время на изготовление",
  ["Cada paso de la ruta dice cuánto tardas en fabricarlo, y la franja de arriba el tiempo de toda la ruta."] = "На каждом шаге маршрута указано время на изготовление, а в верхней панели — общее время всего маршрута.",
  ["Lo que sacas vendiendo en la AH"] = "Выручка от продажи на аукционе",
  ["Bajo el total de la ruta, \"con AH\" dice lo que te quedaría si vendes lo fabricado como aconseja la vista Profit, en la AH y al vendedor."] = "Под итоговой стоимостью маршрута строка «с аукционом» показывает чистый результат, если продать созданное по советам вкладки «Прибыль» (на аукционе и торговцу).",
  ["Menos verdes en las rutas"] = "Меньше зелёных рецептов в маршрутах",
  ["La ruta prefiere recetas seguras a tramos largos en verde: menos fabricaciones y menos viajes a comprar, por muy poco oro más."] = "Маршрут предпочитает надёжные рецепты долгим зелёным отрезкам: меньше созданий и поездок за материалами при минимальной разнице в цене.",
  ["Vender, más fácil"] = "Продавать стало проще",
  ["Vender todo vende todo de un clic, y lo que no tiene un precio fiable en la AH va al vendedor. Con Ctrl+clic derecho en una fila lo pasas de la AH al vendedor o al revés."] = "«Продать всё» продаёт всё в один клик, а товары без надёжной цены аукциона сразу отправляются торговцу. Ctrl+ПКМ по строке переносит предмет между аукционом и торговцем.",
  ["Compras por tandas en verde"] = "Закупка партиями на зелёных рецептах",
  ["En las recetas verdes compra por tandas, con algo de margen, y \"esta tanda: N\" dice para cuántas te llega lo que llevas. El tamaño de la tanda se cambia en /cj opciones, Lista de compra."] = "На зелёных рецептах закупка идёт партиями с небольшим запасом, а «эта партия: N» показывает, на сколько созданий хватит текущих материалов. Размер партии настраивается в /cj opciones («Список покупок»).",
  ["Enfriamientos en el lote de hoy"] = "Рецепты с перезарядкой в партии",
  ["Las transmutaciones y la Mooncloth que tienes listas entran en el Lote de hoy, una cada vez, y vuelven solas cuando están otra vez listas. También salen en las recetas que podrías aprender."] = "Готовые трансмутации и луноткань попадают в «Партию на сегодня» по 1 шт. и автоматически возвращаются после отката. Также отображаются в списке рецептов для изучения.",
  ["Confirmar antes de vender o comprar todo"] = "Подтверждение массовой покупки и продажи",
  ["Vender todo, Comprar todo y vender al vendedor desde el Inventario preguntan antes. Cada aviso se quita con \"No volver a mostrar\" y se vuelve a activar en las opciones."] = "«Продать всё», «Купить всё» и массовая продажа из «Инвентаря» теперь запрашивают подтверждение. Отключается галочкой «Больше не показывать».",
  ["Quita recetas de Ganar dinero"] = "Удаление рецептов из «Заработка»",
  ["Con la X de una fila, Ganar dinero deja de proponerte esa receta (por ejemplo, si pide una estación que no tienes). Se recupera con la fila del final de la lista."] = "Кнопкой X в строке можно убрать рецепт из «Заработка» (например, если у вас нет нужного станка). Возвращается строкой в конце списка.",
  ["Demanda de TSM"] = "Спрос TSM",
  ["Si tienes TSM con su app, Ganar dinero tiene en cuenta cuántas se venden al día en tu región y no te propone fabricar más de lo que se vende. Los mínimos se ajustan en las opciones de Ganar dinero."] = "При наличии TSM с десктопным приложением «Заработок» учитывает дневной объём продаж в регионе и не предлагает создавать больше, чем раскупают.",
  ["La bolsa de componentes cuenta"] = "Учитывается сумка для реагентов",
  ["Lo que llevas en la bolsa de componentes cuenta en la ruta, el Inventario y Ganar dinero, y \"Recoge el correo\" se completa aunque lo recogido vaya a esa bolsa."] = "Предметы в сумке для реагентов теперь учитываются в маршруте, «Инвентаре» и «Заработке», а шаг «Заберите почту» засчитывается, даже если забранное попало в неё.",
  ["Recetas con dos herramientas"] = "Рецепты с двумя инструментами",
  ["Los cascos de ingeniería piden el Blacksmith Hammer y la Arclight Spanner, y la ruta ya pide las dos."] = "Инженерные шлемы требуют и Кузнечный молот, и Тангенциальный вращатель — маршрут теперь запрашивает оба инструмента.",
  ["Gasta lo que sobra"] = "Использование остатков",
  ["Al acabar un paso, si te sobran materiales y fabricar con ellos deja más que venderlos, la ruta te lo propone."] = "После завершения шага, если остались лишние материалы и переработать их выгоднее, чем продать, маршрут предложит это сделать.",
  ["Recetas de lo intermedio"] = "Рецепты промежуточных материалов",
  ["Si algo intermedio pide una receta que no sabes (Stonescale Oil), la ruta tiene una fila para aprenderla y cuenta su precio."] = "Если для промежуточного компонента нужен неизученный рецепт (например, Масло каменного угря), маршрут добавит строку изучения и учтёт его цену.",
  ["Confirmar al anunciar, más fiable"] = "Надёжное подтверждение выставления",
  ["El Sí anuncia antes de cerrar el aviso, el aviso se cierra al cerrar la AH o el vendedor, y ya no dice \"Anunciados\" si la AH no responde."] = "Кнопка «Да» сначала выставляет лот и только потом закрывает окно; диалог закрывается при уходе от аукциона или торговца.",
  ["Rutas que no se quedan en el 99%"] = "Маршруты больше не зависают на 99%",
  ["Si el cálculo de una ruta falla, la página lo dice en vez de quedarse en \"Calculando la ruta… 99%\". E Ingeniería 1-300 vuelve a calcularse rápido."] = "При сбое расчёта страница сразу сообщает об ошибке вместо зависания на «Расчёт маршрута… 99%». Инженерное дело 1–300 снова рассчитывается быстро.",
  ["Herramientas en la lista de la compra"] = "Инструменты в списке покупок",
  ["Si un paso pide una herramienta que no llevas (Arclight Spanner), va a la lista de la compra en vez de darla por hecha."] = "Если для шага нужен инструмент, которого нет в сумках (например, Тангенциальный вращатель), он добавляется в список покупок.",
  ["Transmutaciones en otros idiomas"] = "Трансмутации на других языках",
  ["Con el juego en español, alemán o francés, la ruta ya no pide 186 transmutaciones seguidas: reconoce su enfriamiento."] = "В неанглийских клиентах маршрут больше не предлагает 186 трансмутаций подряд и корректно распознаёт их время восстановления.",
  ["Sin errores en mazmorras"] = "Без ошибок в подземельях",
  ["Las compras de la AH se leen del chat solo con la AH abierta: en mazmorras y en combate ya no salen errores."] = "Покупки на аукционе считываются из чата только при открытом окне аукциона: в подземельях и в бою больше не возникают ошибки.",
  -- Investments tab (InvestUI.lua, Invest.lua)
  ["Inversiones"] = "Инвестиции",
  ["Precio al apuntar una compra o venta"] = "Цена при записи покупки или продажи",
  ["Lo que escribes en el precio: el total (lo que pagaste por todo) o el precio por unidad. En la ventana de compra o venta lo puedes cambiar cada vez."] = "Что вы вводите в поле цены: общую сумму за всю партию или цену за 1 штуку. Можно переключать при каждой записи.",
  ["Último escaneo (%s): nada a este precio; lo más barato, %s"] = "Последний скан (%s): нет лотов по этой цене; самый дешёвый — %s",
