  ["Lista"] = "Список",
  ["Fichas"] = "Карточки",
  ["Una fila por objeto: muchas de un vistazo, con menos scroll."] = "По одной строке на предмет: компактный вид с минимумом прокрутки.",
  ["Dos por fila, con más detalle."] = "Две карточки в ряд с подробной информацией.",
  ["Objeto"] = "Предмет",
  ["Tienes"] = "В наличии",
  ["Tu cartera está vacía. Añade una compra: escribe el nombre del objeto en el buscador de arriba a la derecha."] = "Ваш портфель пуст. Добавьте покупку: введите название предмета в поиске справа вверху.",
  ["Clic: ordenar por esta columna (otro clic: al revés)."] = "Клик: сортировать по этому столбцу (повторный клик — в обратном порядке).",
  ["Precio de %s: puede haber cambiado."] = "Цена из %s: могла измениться.",
  ["Tu precio medio y lo que ganas con cada objeto."] = "Ваша средняя цена закупки и прибыль по каждому предмету.",
  ["%d sin precio: no cuentan en Vale hoy."] = "%d без цены: не учитываются в «Стоит сегодня».",
  ["Tu cartera de inversiones en la AH: lo que compraste, a qué precio medio y cuánto ganas o pierdes con cada objeto."] = "Ваш инвестиционный портфель на аукционе: что куплено, средняя цена и текущая прибыль или убыток.",
  -- Options: Tabs category (order and hide the main window's tabs)
  ["Pestañas"] = "Вкладки",
  ["Ocultar"] = "Скрыть",
  ["OCULTA"] = "СКРЫТА",
  ["Clic: volver a mostrarla."] = "Клик: снова показывать.",
  ["Clic: ocultarla."] = "Клик: скрыть.",
  -- Options: Investments, hide list-view columns
  ["Columnas de la lista"] = "Столбцы списка",
  ["Clic en una columna para ocultarla de la vista de lista (o volver a mostrarla). El nombre del objeto gana el sitio."] = "Нажмите на столбец, чтобы скрыть или вернуть его в режиме списка. Название предмета займёт освободившееся место.",
  ["Arrastra la fila para cambiar el orden. La de arriba es la que se abre al abrir el addon."] = "Перетаскивайте строки, чтобы изменить порядок. Верхняя вкладка открывается первой при запуске аддона.",
  ["Vuelve a poder ordenar las pestañas."] = "Вернуться к изменению порядка вкладок.",
  ["Elige qué pestañas no se ven: clic en cada una y luego Hecho. Su página sigue abriéndose desde la AH o el asistente de ruta."] = "Выберите скрываемые вкладки: нажмите на нужные и затем «Готово». Их страницы по-прежнему открываются с аукциона или из помощника.",
  ["Tiene que quedar al menos una pestaña visible."] = "Должна оставаться видимой хотя бы одна вкладка.",
  ["Lista de compra oculta: ya no tiene pestaña ni brilla al añadirle algo. La lista junto a la Casa de Subastas y la ventana del vendedor siguen igual."] = "Список покупок скрыт: вкладка убрана и не мигает при добавлении. Мини-окно у аукциона и окно у торговца работают как прежде.",
  ["Ordena y oculta las pestañas"] = "Порядок и скрытие вкладок",
  ["En opciones, Pestañas: arrastra las pestañas para ordenarlas y oculta las que no uses. El addon se abre en la de arriba."] = "В настройках («Вкладки») можно перетаскивать вкладки для сортировки и скрывать ненужные. Аддон открывается на верхней вкладке.",
  ["Sin precio: escanea la AH"] = "Нет цены: просканируйте аукцион",
  ["Precios de tus escaneos con Crafter's Journal: se ponen al día cada vez que escaneas."] = "Цены из ваших сканов в Crafter's Journal: обновляются при каждом сканировании.",
  ["Sin precios de este objeto: escanea la AH para ver su evolución."] = "Нет данных о цене этого предмета: просканируйте аукцион, чтобы видеть динамику.",
  ["Del historial de Auctionator"] = "Из истории Auctionator",
  ["De tu escaneo de %s"] = "Из вашего скана (%s)",
  ["De tu escaneo"] = "Из вашего скана",
  ["Subida sin confirmar: más del triple que el día anterior. No cuenta hasta que se repita otro día."] = "Неподтверждённый скачок: более чем в 3 раза выше предыдущего дня. Не учитывается до подтверждения в другой день.",
  ["Día dudoso: mucho más caro que el día de antes y el de después. No cuenta."] = "Сомнительный день: намного дороже, чем днём ранее и днём позже. Не учитывается.",
  ["Subida sin confirmar a %s: no cuenta hasta que se repita otro día."] = "Неподтверждённый скачок до %s: не учитывается до повторения в другой день.",
  ["Sin precio: búscalo en Auctionator"] = "Нет цены: найдите через Auctionator",
  ["Auctionator aún no tiene precios de este objeto: búscalo o escanea con Auctionator."] = "У Auctionator пока нет цен на этот предмет: найдите его или просканируйте аукцион в Auctionator.",
  ["Auctionator aún no deja otro escaneo completo: espera a que acabe su cuenta atrás."] = "Auctionator пока не позволяет запустить новое полное сканирование: дождитесь окончания таймера.",
  ["Auctionator aún no está listo para escanear: espera un momento o vuelve a abrir la AH."] = "Auctionator ещё не готов к сканированию: подождите немного или переоткройте аукцион.",
  [" (con el escaneo de Auctionator)"] = " (по данным скана Auctionator)",
  ["Escaneando con Auctionator... %d s"] = "Сканирование через Auctionator... %d с",
  ["Pidiendo los datos de la AH al servidor... %d s"] = "Запрос данных аукциона у сервера... %d с",
  ["El escaneo lo pide Crafter's Journal."] = "Сканирование запрашивает Crafter's Journal.",
  [" (con el escaneo de Crafter's Journal)"] = " (сканирование Crafter's Journal)",
  ["No se pudo leer el escaneo de Auctionator. Puedes escanear tú cuando el botón lo permita."] = "Не удалось прочитать сканирование Auctionator. Вы можете сканировать сами, когда кнопка это позволит.",
  ["Auctionator acaba de pedir un escaneo completo: el servidor no permitirá otro hasta dentro de %s."] = "Auctionator только что запросил полное сканирование: сервер не позволит следующее ещё %s.",
  ["Has cambiado el modo de escaneo: el escaneo en curso no se guarda."] = "Вы сменили режим сканирования: текущее сканирование не сохраняется.",
  ["Ahora puedes escoger el modo de escaneo para Crafter's Journal"] = "Теперь можно выбрать режим сканирования Crafter's Journal",
  ["Se cambia cuando quieras en /cj opciones, General."] = "Это можно изменить в любое время в /cj opciones («Общие»).",
  ["Modo de escaneo"] = "Режим сканирования",
  ["El botón Escanear lanza el escaneo completo de Auctionator (un escaneo para los dos addons) y la pestaña Inversiones usa su historial de precios."] = "Кнопка «Сканировать» запускает полное сканирование Auctionator (одно сканирование для обоих аддонов), а вкладка «Инвестиции» использует его историю цен.",
  ["No está instalado: Crafter's Journal escanea solo."] = "Не установлен: Crafter's Journal сканирует сам.",
  ["Un solo escaneo para los dos addons. Inversiones usa su historial de precios."] = "Одно сканирование для обоих аддонов. «Инвестиции» используют его историю цен.",
  ["Escanea por su cuenta y solo usa sus propios datos. No hace falta ningún addon más."] = "Сканирует сам и использует только свои данные. Другие аддоны не нужны.",
  ["Crafter's Journal escanea solo y usa únicamente lo suyo: sus escaneos y los 21 días de precios que apunta, nada de Auctionator. Si lo tienes, su botón de escaneo completo espera entonces los 15 min del servidor."] = "Crafter's Journal сканирует сам и использует только свои данные: свои сканы и цены за 21 день, которые он записывает, ничего из Auctionator. Если Auctionator установлен, его кнопка полного сканирования тогда ждёт 15 минут сервера.",
  ["El servidor aún no permite un escaneo completo (quizá otro addon escaneó hace poco). Inténtalo más tarde."] = "Сервер пока не разрешает полный скан (возможно, другой аддон недавно сканировал). Попробуйте позже.",
  ["No se encontró ninguna API de subastas compatible en este cliente."] = "В этом клиенте не найден совместимый API аукциона.",
  ["Con Auctionator: el escaneo lo hace Auctionator (así guarda su historial de precios) y el addon lee esos mismos datos para todas las pestañas."] = "Через Auctionator: сканирование выполняет Auctionator (сохраняя историю цен), а аддон использует эти данные во всех вкладках.",
  ["Auctionator ha hecho un escaneo en modo resumen, que Crafter's Journal no usa (solo trae el precio mínimo de cada objeto). Para actualizar el addon, pulsa Escanear en Crafter's Journal, o activa en las opciones de Auctionator «%s»."] = "Auctionator выполнил сканирование в режиме сводки, которое Журнал ремесленника не использует (в нём только минимальная цена каждого предмета). Чтобы обновить аддон, нажмите «Сканировать» в Журнале ремесленника или включите в настройках Auctionator «%s».",
  ["Auctionator está en modo resumen: su botón Escanear no actualiza Crafter's Journal. Usa este botón, o activa en las opciones de Auctionator «%s»."] = "Auctionator в режиме сводки: его кнопка «Сканировать» не обновляет Журнал ремесленника. Используйте эту кнопку или включите в настройках Auctionator «%s».",
  ["Precios del historial de Auctionator: se ponen al día cada vez que escaneas."] = "Цены из истории Auctionator: обновляются при каждом сканировании.",
  ["Mayús+clic: buscarlo en la AH"] = "Shift+клик: найти на аукционе",
  ["Minería"] = "Горное дело",
  ["con %s"] = "с %s",
  ["neto %s"] = "чистыми %s",
  ["ganas %s"] = "выгода %s",
  ["Cuenta del paso:"] = "Расчёт шага:",
  ["Se recupera vendiéndolo"] = "Вернётся при продаже",
  ["Se recupera (vendido o guardado)"] = "Вернётся (продано или оставлено)",
  ["Aprender la receta va en su propia fila."] = "Изучение рецепта вынесено в отдельную строку.",
  ["Cómo elige la ruta"] = "Как строится маршрут",
  ["De media hacen falta %d y se piden %d (%d de margen), por si los puntos tardan en subir. Si te sobran, sirven para el tramo siguiente."] = "В среднем нужно %d шт., но закупается %d шт. (запас %d) на случай, если очки будут расти медленно. Излишки перейдут на следующий этап.",
  ["La ruta busca la forma más barata de subir contando lo que recuperas: los materiales a precio de la AH (o del vendedor, si sale más barato) menos lo que sacas vendiendo al vendedor lo que fabricas, más el instructor. Por eso a veces elige una receta con materiales más caros: se vende mejor o hacen falta menos fabricaciones. Las guías suelen mirar solo los materiales, así que la ruta puede no coincidir con ellas."] = "Маршрут ищет самый дешёвый способ прокачки с учётом возврата средств: стоимость материалов на аукционе (или у торговца, если дешевле) минус выручка от продажи созданного торговцу плюс цена обучения. Поэтому иногда выбираются более дорогие материалы, если изделие выгоднее продаётся или требует меньше попыток.",
  ["Antes: misión «%s»"] = "Сначала: задание «%s»",
  ["Antes: una misión de %s"] = "Сначала: задание от %s",
  ["El instructor no te la enseña hasta que la hagas."] = "Наставник не обучит рецепту, пока вы его не выполните.",
  ["Las recetas de instructor que piden antes una misión se usan: el paso dice qué misión hacer."] = "Рецепты наставника, для которых сначала нужно задание, используются: шаг подскажет, какое задание выполнить.",
  ["Tampoco se usan las recetas de instructor que piden antes una misión que no has hecho."] = "Рецепты наставника, для которых нужно невыполненное задание, тоже не используются.",
  ["¿No quieres aprender esta receta? Abre la ruta en la ventana (el icono del addon, arriba en el asistente) y quítala con la X de su fila: la ruta busca otra."] = "Не хотите учить этот рецепт? Откройте маршрут в окне (значок аддона вверху помощника) и уберите его кнопкой X в строке: маршрут подберёт другой.",
}
